module OLED_ShowData_Light(
	sys_clk,
	rst_n,
	light_data,
	fontdata,
	show_Lightdata_req,
	write_done,
	show_Lightdata,
	font_row,
	show_Lightdata_finish,
	font,
	font_index_after);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	input [15:0] light_data;
	input [7:0] fontdata;
	input show_Lightdata_req;
	input write_done;
	output [23:0] show_Lightdata;
	output font_row;
	output show_Lightdata_finish;
	output [4:0] font;
	output [3:0] font_index_after;

	wire sys_clk;
	wire rst_n;
	wire [15:0] light_data;
	wire [7:0] fontdata;
	wire show_Lightdata_req;
	wire write_done;
	wire [23:0] show_Lightdata;
	reg font_row;
	wire show_Lightdata_finish;
	reg [4:0] font;
	wire [3:0] font_index_after;

	//----Code starts here: integrated by Robei-----
	    reg[2:0]			font_sel;
		reg[3:0] 		font_index;
		reg[7:0]			show_x;
		reg[3:0]			show_y;
	    reg [15:0] light_data_reg;
		reg[23:0]		showfont_data_reg;
		
	    wire				onefont_finish;
		
	    assign onefont_finish  = (font_row == 1'b1 && font_index == 4'd10 && write_done == 1'b1) ? 1'b1 : 1'b0;
		assign show_Lightdata_finish= (onefont_finish == 1'b1 && font_sel == 3'd4) ? 1'b1 : 1'b0;
		assign show_Lightdata = showfont_data_reg;
		assign font_index_after=font_index - 2'd3;
		always@(*)
		begin
			case(font_index)
			4'd0:	showfont_data_reg <= {8'h78,8'h00,8'hB0 + show_y + font_row};
			4'd1:  showfont_data_reg <= {8'h78,8'h00,8'h00 + show_x[3:0]};
			4'd2:  showfont_data_reg <= {8'h78,8'h00,8'h10 + show_x[7:4]};
			default:	showfont_data_reg <= {8'h78,8'h40,fontdata}; //fontdata
			endcase
		end
		
		always@(posedge sys_clk or negedge rst_n)
		begin
			if(rst_n == 1'b0)
				font_index <=4'd0;
			else if(write_done == 1'b1 && font_index == 4'd10)
				font_index <= 4'd0;
			else if(write_done == 1'b1 && show_Lightdata_req == 1'b1)
				font_index <= font_index + 1'b1;
			else
				font_index <= font_index;
		end
		
		always@(posedge sys_clk or negedge rst_n)
		begin
			if(rst_n == 1'b0)
				font_row <= 1'b0;
			else if(onefont_finish == 1'b1)
				font_row <= 1'b0;
			else if(write_done == 1'b1 && font_index == 4'd10)
				font_row <= 1'b1;
			else
				font_row <= font_row;
		end
		
	   always@(posedge sys_clk or negedge rst_n)
		begin
			if(rst_n == 1'b0)
				font_sel <=3'd0;
			else if(show_Lightdata_finish== 1'b1)
				font_sel <= 3'd0;
			else if(onefont_finish == 1'b1)
				font_sel <= font_sel + 1'b1;
			else
				font_sel <= font_sel;
		end
		
		always@(posedge sys_clk or negedge rst_n)
		begin
			if(rst_n == 1'b0)
			light_data_reg <= 16'd0;
			else
			light_data_reg <= light_data;
	    end
		
	    always@(posedge sys_clk or negedge rst_n)
		begin
			if(rst_n == 1'b0)
			begin
				show_x <= 'd0;
				show_y <= 'd0;
			end
			else if(font_sel == 3'd0)
			begin
				show_x <= 'd52;
				show_y <= 'd6;
			end
			else if(font_sel == 3'd1)
			begin
				show_x <= 'd60;
				show_y <= 'd6;
			end
			else if(font_sel == 3'd2)
			begin
				show_x <= 'd68;
				show_y <= 'd6;
			end
			else if(font_sel == 3'd3)
			begin
				show_x <= 'd76;
				show_y <= 'd6;
			end
			else if(font_sel == 3'd4)
			begin
				show_x <= 'd84;
				show_y <= 'd6;
			end
			else
			begin
				show_x <= 'd0;
				show_y <= 'd0;
			end
		end
		
		always@(posedge sys_clk or negedge rst_n)
		begin
			if(rst_n == 1'b0)
				font <= 'd0;
			else if(font_sel == 3'd4)
				font <=light_data_reg % 4'd10;
			else if(font_sel == 3'd3)
				font <=light_data_reg / 4'd10 % 4'd10;
			else if(font_sel == 3'd2)
				font <=light_data_reg / 7'd100 % 4'd10;	
			else if(font_sel == 3'd1)
				font <=light_data_reg /10'd1000 % 4'd10;
			else if(font_sel == 3'd0)
				font <= light_data_reg /14'd10000 % 4'd1;
			else
				font <= font;		
		end
	
	
	
endmodule    //OLED_ShowData_Light

